/// <summary>
/// A common Logic class for all inventory journal lines
/// </summary>
class MwmsLogicBlockJournalLinesCommon extends MwmsLogicBlock
{
    inventJournalTrans          inventJournalTrans;
    InventJournalTrans_Tag      inventJournalTrans_tag;
    InventJournalTable          inventJournalTable;
    InventDim                   inventDim;
    AddUpdate                   createOrUpdate;

}

Method.Source:
[TFMParameter(AddUpdate::Add,"@TaskletMobileWMS:Addorselectforupdate")]
public MwmsAddUpdate parmCreateOrUpdate(MwmsAddUpdate _createOrUpdate = createOrUpdate)
{
    createOrUpdate = _createOrUpdate;
    return createOrUpdate;
}

protected TFMReferenceDataConfiguration lockWarehouseInHeader(TFMReferenceDataConfiguration _headers)
{
    TFMRegistrationCollector warehouse = _headers.getCollector(extendedTypeStr(InventLocationId));

    if (warehouse)
    {
        warehouse.parmLocked();
    }
    return _headers;
}

protected void getTables()
{
    inventJournalId                     inventJournalId                 = request.getFieldValue(extendedTypeStr(JournalId));
    InventJournalType                   jourType;
    inventJournalTable  = inventJournalTable::find(inventjournalId, true);
    jourType                        = inventJournalTable.JournalType;

    inventJournalTrans_tag = null;
    inventJournalTrans = null;
    if (createOrUpdate == AddUpdate::Update)
    {
        if (jourType == InventJournalType::TagCounting)
        {
            inventJournalTrans_tag = request.getReferredRecord();
        }
        else
        {
            inventJournalTrans  = request.getReferredRecord();
        }
    }
    else
    {
        // Initialize the new journal line
        inventJournalTrans.clear();
        inventJournalTrans_tag.clear();
    }

    if (jourType == InventJournalType::TagCounting)
    {
        components.provideDataIfPossible(inventJournalTrans_tag);
        inventJournalTrans_tag.write();
    }
    else
    {
        components.provideDataIfPossible(inventJournalTrans);
        inventJournalTrans.write();
    }

    components.provideDataIfPossible(inventJournalTable);
    inventJournalTable.write();

}
